content.text:
{
  "primary_meaning": "The Word of God as a source of spiritual illumination, guidance, and direction for the believer's path",
  "primary_basis": [
    "Psalm 119:105",
    "Proverbs 6:23",
    "2 Samuel 22:29 / Psalm 18:28"
  ],
  "alternatives": [
    {
      "meaning": "The seven churches (or the Church collectively) as light-bearers before God",
      "basis": [
        "Revelation 1:12-20",
        "Revelation 2:5"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The human spirit or conscience as searched/illuminated by the Lord",
      "basis": [
        "Proverbs 20:27"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Faithful readiness, spiritual preparedness, or the believer's testimony (often with oil as the Spirit)",
      "basis": [
        "Matthew 25:1-13 (parable of the ten virgins)",
        "Matthew 5:14-16",
        "Luke 12:35"
      ],
      "prominence": "common"
    },
    {
      "meaning": "John the Baptist (or a prophetic witness) as a temporary shining light",
      "basis": [
        "John 5:35"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "The eye as the lamp of the body (spiritual perception or singleness of heart)",
      "basis": [
        "Matthew 6:22-23",
        "Luke 11:34-36"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Psalm 119:105 is the single most frequently cited and taught symbolic use across confessional lines and popular Christian instruction; other meanings are context-specific and well-attested but secondary in frequency of application as a general symbol for 'lamp'."
}
